<p class="eyebrow">KYC review</p><h1><?= e($submission['public_id']) ?></h1><section class="card"><p><?= e($submission['email']) ?> · <?= e($submission['country_name']) ?></p><form method="post" action="<?= e(route('admin.kyc.action',['kyc'=>$submission['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><label>User-facing message<textarea name="message"></textarea></label><label>Private note<textarea name="private_note"></textarea></label><div class="button-row"><button name="action" value="UNDER_REVIEW">Under review</button><button name="action" value="APPROVE">Approve</button><button name="action" value="REJECT">Reject</button><button name="action" value="RESUBMIT">Request resubmission</button></div></form></section><section class="card"><h2>Responses</h2><?php foreach($values as $v): ?><p><strong><?= e($v['field_label']) ?>:</strong> <?= e($v['value_text']) ?></p><?php endforeach; ?><h2>Private documents</h2><?php foreach($documents as $d): ?><p><a href="<?= e(route('admin.kyc.document',['kyc'=>$submission['id'],'document'=>$d['id']])) ?>"><?= e($d['original_filename']) ?></a> (<?= e($d['mime_type']) ?>)</p><?php endforeach; ?></section>
